def _block_bridge_maps(blocks: list[dict],
                      ni: list[str], nj: list[str]) -> tuple[dict, dict]:
    """Fuzzy similarity (0–100, Levenshtein) of internal gap word spans,
    mapped to the gap word indices on each side."""
    bi, bj = {}, {}
    for b in blocks:
        for gi0, gi1, gj0, gj1 in b["gaps"]:
            gi = ni[gi0:gi1]
            gj = nj[gj0:gj1]
            if not gi and not gj:
                continue
            fuzz = round(fuzz_ratio(" ".join(gi), " ".join(gj)), 1)
            for wi in range(gi0, gi1):
                bi[wi] = fuzz
            for wj in range(gj0, gj1):
                bj[wj] = fuzz
    return bi, bj


def _snippet(words, matched, context=6):
    idxs = sorted(matched.keys())
    if not idxs:
        return "", "", 0
    lo, hi = idxs[0], idxs[-1]
    a = max(0, lo - context)
    b = min(len(words), hi + 1 + context)
    snippet = " ".join(words[a:b]).strip()
    rng = f"{lo + 1}–{hi + 1}" if hi > lo else str(lo + 1)
    return snippet, rng, len(idxs)


def _core_sequence(blocks: list[dict], words: list[str]) -> tuple[str, ...]:
    """The longest contiguous matched word run inside the strongest block —
    the pair's 'formula core'.

    Formulaic reuse (a year-end formula, a battle narrative, a treaty clause)
    makes this tuple all but identical across its occurrences, which is what
    lets the result list collapse 20-30 near-identical rows into one topos.
    """
    best_lo = best_len = 0
    for b in blocks:
        run_start = 0
        run_len = 0
        prev = None
        for wi, _wj in b["matches"]:
            if prev is not None and wi == prev + 1:
                run_len += 1
            else:
                run_len, run_start = 1, wi
            if run_len > best_len:
                best_len, best_lo = run_len, run_start
            prev = wi
    if not best_len:
        return ()
    return tuple(words[best_lo:best_lo + best_len])


def _shingles(s: str, k: int = 4) -> frozenset:
    """Character k-grams — a cheap proxy for edit similarity."""
    if len(s) < k:
        return frozenset((s,))
    return frozenset(s[i:i + k] for i in range(len(s) - k + 1))


def cluster_pairs(sigs: list[str], threshold: float = 0.85, min_size: int = 2,
                  max_lev: int = 200000) -> dict:
    """Group pairs that carry the same formulaic core into one topos.

    Pure stdlib — no external clustering library, no numpy. Three stages:
      1. pairs whose core is *verbatim* identical collapse in one dict pass.
         Formulaic reuse is overwhelmingly of this kind, and this stage is
         exact and complete — it cannot lose recall;
      2. the distinct cores are then compared against each other (not the pairs
         against each other — a repeated formula makes ~93% of the pair-wise
         comparisons redundant repeats of one core-vs-core test, measured);
      3. within stage 2, candidates survive a sorted-length window and a
         4-gram Jaccard gate before the Levenshtein DP runs.

    Stage 2 stops at `max_lev` comparisons and reports `truncated`, and stage 3's
    gate is a *heuristic*: it can drop a core pair whose edit ratio clears the
    threshold but whose 4-grams diverge. Measured against a provably sound
    multiset bound it grouped 2746 vs 2749 unions on a 3966-pair self-compare
    (~0.1%), for a 9x speedup — the trade is deliberate and the cap is surfaced
    rather than silently dropping work.

    Returns {"clusters": [...], "pair_cluster": [...], "stats": {...}} where
    each cluster is {"id", "size", "members"} with members = pair indices.
    """
    n = len(sigs)
    if n == 0:
        return {"clusters": [], "pair_cluster": [],
                "stats": {"n_pairs": 0, "n_cores": 0, "n_clusters": 0,
                          "n_clustered": 0, "n_singletons": 0,
                          "lev_compares": 0, "truncated": False}}

    # Collapse to distinct cores. `uid` maps each pair to its core's id; the
    # union-find then runs over cores, and pair indices are folded in at the end.
    uid_of_core: dict[str, int] = {}
    uid = [0] * n
    for p, s in enumerate(sigs):
        i = uid_of_core.get(s)
        if i is None:
            i = uid_of_core[s] = len(uid_of_core)
        uid[p] = i
    cores = [None] * len(uid_of_core)
    for s, i in uid_of_core.items():
        cores[i] = s
    U = len(cores)

    uparent = list(range(U))

    def ufind(x: int) -> int:
        while uparent[x] != x:
            uparent[x] = uparent[uparent[x]]
            x = uparent[x]
        return x

    def uunion(a: int, b: int) -> None:
        ra, rb = ufind(a), ufind(b)
        if ra != rb:
            uparent[max(ra, rb)] = min(ra, rb)

    # stage 2 — near-duplicate cores, prefiltered
    by_len = sorted(range(U), key=lambda i: len(cores[i]))
    sh = [_shingles(s) for s in cores]
    lev_compares = 0
    truncated = False
    for a in range(U):
        ia = by_len[a]
        la = len(cores[ia])
        ha = sh[ia]
        if la < 2:
            continue
        for b in range(a + 1, U):
            ib = by_len[b]
            lb = len(cores[ib])
            # |la-lb| alone puts the ratio out of reach, and lengths are
            # non-decreasing here -> no further candidate can qualify either.
            if (lb - la) / (la + lb) > 1.0 - threshold:
                break
            if ufind(ia) == ufind(ib):
                continue
            hb = sh[ib]
            inter = len(ha & hb)
            if not inter:
                continue
            # 4-gram Jaccard as a cheap proxy for edit similarity
            if 2 * inter / (len(ha) + len(hb)) < threshold * 0.5:
                continue
            if lev_compares >= max_lev:
                truncated = True
                break
            lev_compares += 1
            if levenshtein_ratio(cores[ia], cores[ib]) >= threshold:
                uunion(ia, ib)
        if truncated:
            break

    # fold cores -> pairs
    groups: dict[int, list[int]] = {}
    for p in range(n):
        groups.setdefault(ufind(uid[p]), []).append(p)

    clusters = [{"size": len(m), "members": m}
                for m in groups.values() if len(m) >= min_size]
    clusters.sort(key=lambda c: (-c["size"], c["members"][0]))
    for cid, c in enumerate(clusters):
        c["id"] = cid

    pair_cluster = [-1] * n
    for c in clusters:
        for i in c["members"]:
            pair_cluster[i] = c["id"]

    clustered = sum(c["size"] for c in clusters)
    return {
        "clusters": clusters,
        "pair_cluster": pair_cluster,
        "stats": {
            "n_pairs": n,
            "n_cores": U,
            "n_clusters": len(clusters),
            "n_clustered": clustered,
            "n_singletons": n - clustered,
            "lev_compares": lev_compares,
            "truncated": truncated,
        },
    }


