    """Normalized-word n-grams (tuples) used as the candidate-generation key.
    Sparse and discriminative — this is what makes recall scale to many units."""
    if len(words) < n:
        return []
    return [tuple(words[k:k + n]) for k in range(len(words) - n + 1)]


