    _cmpTotal = ev.n_chosen || ev.n_candidates || 0;
    const info = document.querySelector(".cmp-info");
    if (info) info.innerHTML = _cmpInfoHtml();
    setCmpStatus("searching for matches…", 0, 0);
  } else if (ev.t === "pair") {
