  } else if (ev.t === "clusters") {
    // Formulaic duplicates grouped into toposz clusters. Member indices refer
    // to the pairs array in the order it was streamed, which is the order we
    // pushed them — so they index straight into result.pairs.
    _cmpLast.result.clusters = ev.clusters || [];
    _cmpLast.result.cluster_stats = ev.stats || {};
    const info = document.querySelector(".cmp-info");
    if (info) info.innerHTML = _cmpInfoHtml();
  } else if (ev.t === "progress") {
    const frac = ev.total ? ev.done / ev.total : null;
    setCmpStatus(null, frac, ev.found);
  } else if (ev.t === "done") {
    _cmpLast.result.n_pairs_shown = _cmpLast.result.pairs.length;
    renderCmpPairs();
    setCmpDone(ev.found != null ? ev.found : _cmpLast.result.pairs.length);
  } else if (ev.t === "error") {
